"""Build FEATURE_LEDGER.json from the journey results: four separate facts per capability (implemented, executed, environment/assumptions, unresolved limitations)."""
import json, sys
from pathlib import Path
res = json.load(open(sys.argv[1])); by = {r['journey']: r for r in res['results']}
def ex(ns):
    st = [by[n]['status'] for n in ns if n in by]
    return {'journeys': ns, 'statuses': st, 'executed': all(s == 'passed' for s in st) and bool(st)}
ENV = 'one authorized host; two separately configured domains as separate processes/homes under the same operator; simulation provider mode; METACOIN_X402_DISABLED=1; facilitator URL points at a closed loopback port; zero-value development asset; development keys service-custodied'
