ledger = {'schema': 'metacoin-feature-ledger/v2', 'source': res.get('revision'), 'capabilities': [dict(capability=c, implemented=i, executed=ex(j), environment_assumptions=e, unresolved_limitations=u) for c, i, j, e, u in caps]}
